INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-mobile-first', 0, 'lab', 'Сначала мобильная версия', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Карточки .cards лежат во флекс-контейнере. По умолчанию (узкий экран) они идут столбиком, а от ширины окна 600px и больше — в ряд. Пишите «от малого к большому»: обычные правила для телефона, а расширение — в @media (min-width: …).', '', 'Сначала .cards { display: flex; flex-direction: column; gap: 12px; }, потом @media (min-width: 600px) { .cards { flex-direction: row; } }.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-breakpoints-grid', 1, 'lab', 'Сетка с двумя брейкпоинтами', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Блок .gallery — сетка. На телефоне (до 600px) одна колонка, от 600px — две равные колонки, от 960px — три. Используйте grid-template-columns с repeat(…, 1fr) и два @media (min-width: …). Стили проверяются при ширине 360, 700 и 1100px.', '', 'Базовое правило: grid-template-columns: 1fr. Затем @media (min-width: 600px) с repeat(2, 1fr) и @media (min-width: 960px) с repeat(3, 1fr), в таком порядке.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-nav-switch', 2, 'lab', 'Меню и «бургер»', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. На узком экране видна только кнопка .burger, а список .menu скрыт. От ширины 768px, наоборот, меню показывается как flex-ряд, а кнопка исчезает. Стили проверяются при 360 и 1000px; пишите в подходе «сначала мобильная версия».', '', 'База: .menu { display: none; } и .burger { display: block; }. В @media (min-width: 768px): .menu { display: flex; } и .burger { display: none; }.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-fluid-image', 3, 'lab', 'Картинка по ширине колонки', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Фото .photo внутри колонки .col никогда не должно вылезать за её край и не должно искажаться. Задайте max-width: 100% и height: auto. Для обложки .cover (шириной в колонку) поставьте object-fit: cover и соотношение сторон aspect-ratio: 16 / 9.', '', 'img { max-width: 100%; height: auto; } для обложки — width: 100%; aspect-ratio: 16 / 9; object-fit: cover.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-dark-scheme', 4, 'lab', 'Тёмная тема по настройке системы', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Цвета страницы вынесены в переменные --bg и --fg. По умолчанию (светлая тема): фон #ffffff, текст #1a1a1a. Если пользователь выбрал тёмную тему в системе, переопределите их в @media (prefers-color-scheme: dark): фон #121212, текст #eeeeee. Элемент body берёт цвета из переменных.', '', 'На :root задайте обе переменные для светлой темы, затем @media (prefers-color-scheme: dark) { :root { --bg: …; --fg: …; } }, а body { background: var(--bg); color: var(--fg); }.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-hover-media', 5, 'lab', 'Наведение только для мыши', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. У ссылки .link при наведении цвет должен становиться #e11d48, а в обычном состоянии — #2563eb. На сенсорных экранах «наведения» нет, поэтому правило с :hover оберните в @media (hover: hover).', '', '.link { color: #2563eb; } @media (hover: hover) { .link:hover { color: #e11d48; } }', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-container-query', 6, 'lab', 'Контейнерный запрос', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Карточка .card живёт в боксе .box и должна подстраиваться под ширину бокса, а не окна. Сделайте .box контейнером (container-type: inline-size). Пока бокс уже 480px, карточка — блок (display: block). Начиная с 480px, карточка — flex-ряд. Используйте @container.', '', '.box { container-type: inline-size; } .card { display: block; } @container (min-width: 480px) { .card { display: flex; } }', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-container-named', 7, 'lab', 'Именованный контейнер', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Дайте контейнеру .sidebar имя widgets (container-name: widgets) и тип inline-size. Когда он шире 300px, список .tags становится flex-контейнером с переносом (flex-wrap: wrap); уже — остаётся обычным блоком. Условие записывайте с именем: @container widgets (min-width: 300px).', '', 'container-name: widgets; container-type: inline-size; на .sidebar. Затем @container widgets (min-width: 300px) { .tags { display: flex; flex-wrap: wrap; } }.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-clamp-title', 8, 'lab', 'Заголовок на clamp()', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Размер h1 должен плавно расти вместе с шириной окна: не меньше 24px (1.5rem), не больше 48px (3rem), а между ними — 5vw. Запишите одним значением через clamp(). Проверяется при ширине 320, 800 и 1400px.', '', 'h1 { font-size: clamp(1.5rem, 5vw, 3rem); }', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-clamp-space', 9, 'lab', 'Резиновые отступы', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Внутренний отступ блока .hero должен быть «резиновым»: не меньше 16px, не больше 48px, посередине — 4vw. Задайте боковые отступы (padding-left и padding-right) через clamp(…). При 320px они равны 16px, при 800px — 32px, при 1400px — 48px.', '', '.hero { padding-left: clamp(16px, 4vw, 48px); padding-right: clamp(16px, 4vw, 48px); }', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-hover-lift', 10, 'lab', 'Карточка, которая приподнимается', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. При наведении карточка .card должна сдвигаться вверх на 4px (transform: translateY(-4px)). Чтобы движение было плавным, в обычном состоянии задайте переход только по transform: transition-property transform, длительность 0.2s, функция ease-out.', '', '.card { transition: transform 0.2s ease-out; } .card:hover { transform: translateY(-4px); }', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-button-states', 11, 'lab', 'Состояния кнопки', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Кнопка .btn: при наведении фон #1d4ed8, при нажатии (:active) она слегка уменьшается — transform: scale(0.97), а при фокусе с клавиатуры (:focus-visible) получает контур 3px solid #f59e0b. Обычный фон — #2563eb.', '', '.btn { background: #2563eb; } .btn:hover { background: #1d4ed8; } .btn:active { transform: scale(0.97); } .btn:focus-visible { outline: 3px solid #f59e0b; }', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-tooltip-fade', 12, 'lab', 'Подсказка с плавным появлением', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Подсказка .tip скрыта (opacity: 0). Когда пользователь наводит курсор на обёртку .has-tip, подсказка становится полностью видимой (opacity: 1). Анимируйте только прозрачность: transition-property opacity, длительность 0.25s.', '', '.tip { opacity: 0; transition: opacity 0.25s; } .has-tip:hover .tip { opacity: 1; }', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-transform-values', 13, 'lab', 'Три преобразования', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Задайте элементам трансформации: .a сдвиньте вправо на 40px (translateX), .b поверните на 45 градусов (rotate), .c увеличьте в 1.5 раза (scale), а точку, вокруг которой он растёт, поставьте в левый верхний угол (transform-origin: left top).', '', '.a { transform: translateX(40px); } .b { transform: rotate(45deg); } .c { transform: scale(1.5); transform-origin: left top; }', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-drawer', 14, 'lab', 'Выдвижная панель без перерисовки', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Боковая панель .drawer спрятана за левым краем: transform: translateX(-100%). У открытой панели .drawer.open преобразование сбрасывается (translateX(0)). Анимируйте только transform — не left и не width: transition-property transform, 0.3s, ease-out.', '', '.drawer { transform: translateX(-100%); transition: transform 0.3s ease-out; } .drawer.open { transform: translateX(0); }', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-keyframes-pulse', 15, 'lab', 'Пульсация через @keyframes', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Опишите анимацию pulse: в середине (50%) значок увеличивается через transform: scale(1.2). Подключите её к .dot одной строкой: имя pulse, длительность 1.5s, ease-in-out, бесконечно (infinite).', '', '@keyframes pulse { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.2); } } .dot { animation: pulse 1.5s ease-in-out infinite; }', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-fade-in', 16, 'lab', 'Появление с сохранением конечного кадра', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Окно .toast должно плавно появляться: @keyframes fade-in меняет opacity от 0 до 1. Анимация идёт 0.4s и один раз; после окончания окно остаётся видимым, а до старта (при задержке) уже скрыто. Задайте для этого animation-fill-mode: both.', '', '@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } } .toast { animation: fade-in 0.4s ease-out both; }', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 21, 'w21-reduced-motion', 17, 'lab', 'Уважаем «уменьшить движение»', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Индикатор .spinner крутится бесконечно (анимация уже описана в стилях задания). Пользователям с включённой настройкой «уменьшить движение» вращение мешает. Добавьте @media (prefers-reduced-motion: reduce), внутри которого для .spinner отключите анимацию: animation: none.', '', '@media (prefers-reduced-motion: reduce) { .spinner { animation: none; } }', '{}');
